import React, { useState, useEffect } from "react";
import productService from "../../services/productService";

const ProductList = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        // Gọi API lấy danh sách sản phẩm từ axiosClient bạn đưa
        const response = await productService.getAllProducts();
        
        /* LƯU Ý: Tùy thuộc vào phía Backend trả về dạng nào:
          - Nếu Backend trả trực tiếp mảng: setProducts(response)
          - Nếu Backend bọc trong object data: setProducts(response.data)
          Dưới đây mình tạm để response.data (phổ biến nhất của axios), nếu bị trống bạn hãy thử đổi thành setProducts(response) nhé.
        */
        setProducts(response.data || response);
      } catch (error) {
        console.error("Lỗi khi tải danh sách sản phẩm:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  // Giao diện khi đang đợi API tải dữ liệu (Loading Skeleton)
  if (loading) {
    return (
      <div className="row g-4">
        {[1, 2, 3, 4].map((n) => (
          <div className="col-12 col-sm-6 col-md-4 col-lg-3" key={n}>
            <div className="card border-0 p-3 shadow-sm placeholder-glow" style={{ height: "350px" }}>
              <div className="placeholder bg-secondary opacity-10 rounded-3 w-100 h-50 mb-3"></div>
              <div className="placeholder bg-secondary opacity-10 w-75 mb-2"></div>
              <div className="placeholder bg-secondary opacity-10 w-50"></div>
            </div>
          </div>
        ))}
      </div>
    );
  }

  // Trường hợp API chạy thành công nhưng không có sản phẩm nào
  if (products.length === 0) {
    return <p className="text-center text-muted my-5">Hiện chưa có sản phẩm nào được hiển thị.</p>;
  }

  return (
    /* g-4 giúp tạo khoảng cách thoáng đãng giữa các card sản phẩm
       col-12 (mobile: 1 cột), col-sm-6 (màn hình nhỏ: 2 cột), col-lg-3 (máy tính: 4 cột nằm ngang tăm tắp) 
    */
    <div className="row g-4">
      {products.map((product) => (
        <div className="col-12 col-sm-6 col-md-4 col-lg-3" key={product.id || product._id}>
          <div className="modern-product-card border-0 rounded-3 shadow-sm bg-white overflow-hidden h-100 d-flex flex-column justify-content-between position-relative">
            
            {/* 1. Khung chứa ảnh sản phẩm nền xám nhạt cực sang */}
            <div 
              className="product-img-wrapper p-4 d-flex align-items-center justify-content-center" 
              style={{ height: "220px", backgroundColor: "#f8f9fa" }}
            >
              <img 
                src={product.image || "https://placehold.co/300x300?text=No+Image"} 
                className="img-fluid object-fit-contain h-100" 
                alt={product.name} 
                onError={(e) => { e.target.src = "https://placehold.co/300x300?text=No+Image" }} // Ảnh lỗi thì đổi ảnh mặc định
              />
            </div>
            
            {/* 2. Phần thông tin chi tiết sản phẩm */}
            <div className="p-3 text-center d-flex flex-column flex-grow-1 justify-content-between">
              <div>
                <h5 className="fs-6 fw-medium text-dark text-truncate mb-1" title={product.name}>
                  {product.name}
                </h5>
                <p className="text-muted small text-truncate mb-2" style={{ fontSize: "0.8rem" }}>
                  {product.description || "Thiết kế thông minh, hiện đại"}
                </p>
              </div>
              
              <div>
                {/* Định dạng giá tiền VNĐ cho chuẩn chỉnh */}
                <p className="text-dark fw-bold mb-3 fs-6">
                  {typeof product.price === 'number' 
                    ? product.price.toLocaleString('vi-VN', { style: 'currency', currency: 'VND' }) 
                    : `${product.price}`}
                </p>
                
                {/* Nút thêm vào giỏ dạng viền đen bo tròn thanh lịch */}
                <button className="btn btn-outline-dark btn-sm w-100 rounded-pill px-4 transition-all">
                  Thêm vào giỏ
                </button>
              </div>
            </div>

          </div>
        </div>
      ))}
    </div>
  );
};

export default ProductList;
